const PROFILE_DEFAULT={name:"",industry:"Technology / SaaS",size:"11–50",status:"private",customers:[],markets:[],regulated:[],driver:"tender",work:"hybrid",hosting:"cloud",dev:"none",services:[],availability:"low",ai:"use",it:"inhouse",suppliers:"few",data:[],payments:"none",footprint:["office"],esgAsk:"no",certs:[]};
const has=(p,k,v)=>Array.isArray(p[k])&&p[k].includes(v);
const isProvider=p=>has(p,"services","saas")||has(p,"services","msp")||has(p,"services","dc");
const isHealth=p=>p.industry==="Healthcare"||has(p,"data","health")||has(p,"regulated","moh")||has(p,"customers","hc");
const isGov=p=>p.industry==="Government vendor"||has(p,"customers","gov");
const isFiSide=p=>has(p,"regulated","mas")||has(p,"customers","fi")||p.industry==="Financial services";

